        prerequisites) printf '%s' 'Check the system' ;;
        repository) printf '%s' 'Download Indus Agent' ;;
        runtime) printf '%s' 'Install uv and Python' ;;
        dependencies) printf '%s' 'Install the Python packages' ;;
        config) printf '%s' 'Prepare the settings' ;;
        products) printf '%s' 'Install the indus command' ;;
        setup) printf '%s' 'Set up a model provider' ;;
        gateway) printf '%s' 'Set up the messaging gateway' ;;
