# <<< generated: stages <<<

# Indus Agent installer: the repository stage (P23-04, R10.14).
#
# A fresh install clones into a hidden sibling staging directory and renames the finished tree
# into place, so an interrupted or failed clone never leaves a target directory behind. An existing
# checkout moves forward on its channel; local edits are stashed and commits that a reset would
# drop are saved under refs/indus/install-backups/ first.

ins_repo_url() { printf '%s' "${INDUS_INSTALL_REPO_URL:-https://github.com/$INS_REPO_SLUG.git}"; }

# Whether URL names our own repository (forks and mirrors follow their branch by default).
ins_is_official() {
    local url slug
    url="$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')"
    slug="$(printf '%s' "$INS_REPO_SLUG" | tr '[:upper:]' '[:lower:]')"
    url="${url%/}"
    url="${url%.git}"
    case "$url" in
        "https://github.com/$slug" | "git@github.com:$slug" | "ssh://git@github.com/$slug") return 0 ;;
    esac
    return 1
}

ins_sha256_text() {
    if command -v sha256sum >/dev/null 2>&1; then
        printf '%s' "$1" | sha256sum | cut -d' ' -f1
    elif command -v shasum >/dev/null 2>&1; then
        printf '%s' "$1" | shasum -a 256 | cut -d' ' -f1
    else
        return 1
    fi
}

# The id an install's settings are kept under: the first 16 hex of SHA-256 of its real path.
ins_install_id() {
    local real digest
    real="$(cd "$1" 2>/dev/null && pwd -P)" || return 1
    digest="$(ins_sha256_text "$real")" || return 1
    printf '%s' "${digest:0:16}"
}

# ins_install_setting DIR NAME: updates.installs.<id>.<NAME> from <home>/config.yaml (the schema
# key `indus update` reads, P23-17), read without Python from the block YAML the settings writer
# produces. A scalar prints as it is; a list (block `- item` lines or `[a, b]`) prints as its
# items separated by spaces. Prints nothing when absent or unreadable.
ins_install_setting() {
    local config="$IN_HOME/config.yaml" id
    [ -f "$config" ] || return 0
    id="$(ins_install_id "$1")" || return 0
    awk -v id="$id" -v want="$2" -v q="'" '
        function clean(s,   f) {
            sub(/^[ \t]+/, "", s)
            sub(/[ \t]+#.*$/, "", s)
            sub(/[ \t\r]+$/, "", s)
            f = substr(s, 1, 1)
            if (length(s) >= 2 && (f == "\"" || f == q) && substr(s, length(s), 1) == f) {
                s = substr(s, 2, length(s) - 2)
            }
            return s
        }
        function flow(s,   n, i, parts, out) {
            s = substr(s, 2, length(s) - 2)
            n = split(s, parts, ",")
            out = ""
            for (i = 1; i <= n; i++) {
                parts[i] = clean(parts[i])
                if (parts[i] != "") out = out (out == "" ? "" : " ") parts[i]
            }
            return out
        }
        /^[ \t]*(#|\r?$)/ { next }
        collecting {
            match($0, /^ */)
            if (RLENGTH >= keyindent && substr($0, RLENGTH + 1, 2) == "- ") {
                items = items (items == "" ? "" : " ") clean(substr($0, RLENGTH + 3))
                next
            }
            print items
            done = 1
            exit
        }
        {
            match($0, /^ */)
            indent = RLENGTH
            rest = substr($0, indent + 1)
            colon = index(rest, ":")
            if (colon == 0) next
            while (depth > 0 && level[depth] >= indent) depth--
            depth++
            level[depth] = indent
            name[depth] = clean(substr(rest, 1, colon - 1))
            if (depth == 4 && name[1] == "updates" && name[2] == "installs" && name[3] == id \
                && name[4] == want) {
                value = clean(substr(rest, colon + 1))
                if (value == "") {
                    collecting = 1
                    keyindent = indent
                    items = ""
                    next
                }
                if (substr(value, 1, 1) == "[" && substr(value, length(value), 1) == "]") {
                    value = flow(value)
                }
                print value
                done = 1
                exit
            }
        }
        END { if (collecting && !done) print items }' "$config"
}

ins_saved_channel() {
    ins_install_setting "$1" channel | grep -E '^(stable|canary|main)$' || :
}

# ins_effective_channel ORIGIN_URL SAVED: an explicit choice, else a pin follows its branch, else
# the saved choice, else stable for our repository's main line and main for anything else.
ins_effective_channel() {
    if [ -n "$IN_CHANNEL" ]; then
        printf '%s' "$IN_CHANNEL"
    elif [ -n "$IN_COMMIT" ]; then
        printf main
    elif [ -n "$2" ]; then
        printf '%s' "$2"
    elif [ "$IN_BRANCH" = main ] && ins_is_official "$1"; then
        printf stable
    else
        printf main
    fi
}

INS_STABLE_TAG='^v[0-9]{1,3}\.[0-9]+\.[0-9]+$'
INS_CANARY_TAG='^v[0-9]{1,3}\.[0-9]+\.[0-9]+-canary\.[0-9]{8}T[0-9]{6}Z$'

ins_valid_stable() { printf '%s\n' "$1" | grep -Eq "$INS_STABLE_TAG"; }

# The newest tag on stdin by SemVer order: X.Y.Z numerically, a canary below its own stable and
# canaries of one X.Y.Z by stamp. MODE stable keeps stable tags only; canary keeps both.
ins_newest_tag() {
    local pattern="$INS_STABLE_TAG"
    [ "$1" != canary ] || pattern="$INS_STABLE_TAG|$INS_CANARY_TAG"
    grep -E "$pattern" | awk -F'[v.-]' '{
        rank = ($5 == "canary") ? "1" $6 : "2"
        printf "%06d%06d%06d%s %s\n", $2, $3, $4, rank, $0
    }' | sort | tail -n 1 | cut -d' ' -f2
}

ins_remote_tags() {
    git ls-remote --tags --refs "$1" 'refs/tags/v*' 2>/dev/null | sed 's#.*refs/tags/##'
}

ins_api_latest() {
    curl -fsSL --connect-timeout 5 --max-time 20 -H 'Accept: application/vnd.github+json' \
        "https://api.github.com/repos/$INS_REPO_SLUG/releases/latest" 2>/dev/null |
        grep -o '"tag_name"[[:space:]]*:[[:space:]]*"[^"]*"' | head -n 1 | sed 's/.*"\([^"]*\)"$/\1/'
}

ins_redirect_latest() {
    curl -fsSI --connect-timeout 5 --max-time 20 \
        "https://github.com/$INS_REPO_SLUG/releases/latest" 2>/dev/null |
        tr -d '\r' | sed -n 's#^[Ll]ocation:.*/releases/tag/\([^/]*\)$#\1#p' | tail -n 1
}

# ins_resolve_release CHANNEL ORIGIN_URL: the tag to install, or nothing when none answers.
# Stable: the GitHub API, then the releases/latest redirect (both for our repository only), then
# the remote's tags. Canary: the newest of the remote's canary and stable tags.
ins_resolve_release() {
    local tag=""
    if [ "$1" = stable ]; then
        if ins_is_official "$2"; then
            tag="$(ins_api_latest)"
            ins_valid_stable "$tag" || tag="$(ins_redirect_latest)"
        fi
        ins_valid_stable "$tag" || tag="$(ins_remote_tags "$2" | ins_newest_tag stable)"
        ins_valid_stable "$tag" || tag=""
    else
        tag="$(ins_remote_tags "$2" | ins_newest_tag canary)"
    fi
    printf '%s' "$tag"
}

# Park local edits before the tree moves: unmerged index entries are cleared first (a stash
# refuses them), then everything, untracked files included, goes into a labelled stash.
ins_park_local_changes() {
    local label="indus-install-autostash-$1"
    [ -n "$(git -C "$IN_DIR" status --porcelain 2>/dev/null)" ] || return 0
    if [ -n "$(git -C "$IN_DIR" ls-files --unmerged 2>/dev/null)" ]; then
        ins_warn "clearing unmerged index entries left by an earlier conflict"
        git -C "$IN_DIR" reset -q >/dev/null 2>&1 ||
            ins_fail "cannot clear the unmerged index in $IN_DIR" local_changes_blocked
    fi
    ins_run "Saving local changes" git -C "$IN_DIR" stash push --include-untracked -m "$label" ||
        ins_fail "could not save the local changes in $IN_DIR; commit or move them, then rerun" local_changes_blocked
    ins_warn "local changes saved in the stash '$label' (see: git -C \"$IN_DIR\" stash list)"
}

ins_repo_fresh() {
    local dir="$IN_DIR" url branch="$IN_BRANCH" channel tag="" target="" parent staged
    local attempt cloned=false no_checkout="" checked=false
    url="$(ins_repo_url)"
    if [ -e "$dir" ] || [ -L "$dir" ]; then
        if [ -d "$dir" ] && [ ! -L "$dir" ] && [ -z "$(ls -A "$dir" 2>/dev/null)" ]; then
            rmdir "$dir" || ins_fail "cannot take over the empty directory $dir" filesystem_error
        else
            ins_fail "$dir exists and is not an Indus Agent checkout; move it aside or pass --dir PATH" dir_not_checkout
        fi
    fi
    channel="$(ins_effective_channel "$url" "")"
    if [ "$channel" != main ]; then
        tag="$(ins_resolve_release "$channel" "$url")"
        [ -n "$tag" ] ||
            ins_fail "could not find the newest $channel release; rerun to try again, or pass --channel main to install the main branch" release_lookup_failed
        ins_info "Installing $tag (the $channel channel; --channel main follows every commit)"
    fi
    [ -z "$IN_COMMIT$tag" ] || no_checkout=--no-checkout
    parent="$(dirname "$dir")"
    mkdir -p "$parent" || ins_fail "cannot create $parent" filesystem_error
    staged="$(mktemp -d "$parent/.indus-clone-XXXXXX")" || ins_fail "cannot create a staging directory in $parent" filesystem_error
    INS_CLEANUP="$staged"
    for attempt in 1 2 3; do
        if ins_run --may-fail "Cloning $url ($branch), attempt $attempt of 3" \
            git clone --filter=blob:none ${no_checkout:+"$no_checkout"} --branch "$branch" "$url" "$staged/tree"; then
            cloned=true
            break
        fi
        rm -rf "$staged/tree"
        [ "$attempt" -eq 3 ] || ins_sleep "$((attempt * 5))"
    done
    if [ "$cloned" = false ]; then
        ins_warn "cloning failed 3 times; trying once more without checking out the files"
        if ins_run --may-fail "Cloning $url ($branch) without a checkout" \
            git clone --filter=blob:none --no-checkout --branch "$branch" "$url" "$staged/tree"; then
            cloned=deferred
        else
            rm -rf "$staged/tree"
            ins_fail "git clone failed; nothing was installed$(ins_cause)" git_clone_failed
        fi
    fi
    if [ -n "$IN_COMMIT" ]; then
        git -C "$staged/tree" merge-base --is-ancestor "$IN_COMMIT" "origin/$branch" 2>/dev/null ||
            ins_fail "commit $IN_COMMIT is not on branch $branch; nothing was installed" commit_not_on_branch
        target="$IN_COMMIT"
    elif [ -n "$tag" ]; then
        ins_run --may-fail "Fetching $tag" git -C "$staged/tree" fetch origin "+refs/tags/$tag:refs/tags/$tag" ||
            ins_fail "could not fetch $tag$(ins_cause); rerun, or pass --channel main" release_lookup_failed
        target="$tag"
    fi
    if [ -n "$target" ] || [ "$cloned" = deferred ]; then
        for attempt in 1 2; do
            if [ -n "$target" ]; then
                ins_run --may-fail "Checking out $target (attempt $attempt of 2)" \
                    git -C "$staged/tree" checkout --force --detach "$target" && checked=true
            else
                ins_run --may-fail "Checking out the files (attempt $attempt of 2)" \
                    git -C "$staged/tree" reset --hard HEAD && checked=true
            fi
            [ "$checked" = false ] || break
            [ "$attempt" -eq 2 ] || ins_sleep 5
        done
        [ "$checked" = true ] ||
            ins_fail "could not check out ${target:-the files}; nothing was installed$(ins_cause)" git_checkout_failed
    fi
    mv "$staged/tree" "$dir" || ins_fail "could not move the new checkout into $dir" filesystem_error
    rmdir "$staged" 2>/dev/null || :
    INS_CLEANUP=""
    ins_ok "cloned into $dir"
}

ins_repo_update() {
    local dir="$IN_DIR" url saved="" channel tag stamp ahead backup
    if [ -n "${INDUS_INSTALL_REPO_URL:-}" ]; then
        git -C "$dir" remote set-url origin "$INDUS_INSTALL_REPO_URL" ||
            ins_fail "cannot point origin at $INDUS_INSTALL_REPO_URL" git_fetch_failed
    fi
    url="$(git -C "$dir" config --get remote.origin.url 2>/dev/null)" || url=""
    [ -n "$IN_CHANNEL$IN_COMMIT" ] || saved="$(ins_saved_channel "$dir")"
    channel="$(ins_effective_channel "$url" "$saved")"
    stamp="$(ins_stamp)"
    if [ -n "$IN_COMMIT" ]; then
        ins_run "Fetching origin/$IN_BRANCH" git -C "$dir" fetch origin "+refs/heads/$IN_BRANCH:refs/remotes/origin/$IN_BRANCH" ||
            ins_fail "git fetch failed$(ins_cause)" git_fetch_failed
        git -C "$dir" merge-base --is-ancestor "$IN_COMMIT" "origin/$IN_BRANCH" 2>/dev/null ||
            ins_fail "commit $IN_COMMIT is not on branch $IN_BRANCH" commit_not_on_branch
        ins_park_local_changes "$stamp"
        ins_run "Checking out $IN_COMMIT" git -C "$dir" checkout --detach "$IN_COMMIT" ||
            ins_fail "git checkout failed$(ins_cause)" git_checkout_failed
        return 0
    fi
    if [ "$channel" != main ]; then
        tag="$(ins_resolve_release "$channel" "$url")"
        if [ -z "$tag" ] || ! ins_run --may-fail "Fetching $tag" git -C "$dir" fetch origin "+refs/tags/$tag:refs/tags/$tag"; then
            if [ -n "$IN_CHANNEL" ]; then
                ins_fail "could not reach the newest $channel release$(ins_cause); rerun, or pass --channel main" release_lookup_failed
            fi
            ins_warn "could not reach the newest $channel release; keeping $dir as it is"
            return 0
        fi
        # A release only moves a checkout forward; any other move is `indus update`'s decision.
        if git -C "$dir" merge-base --is-ancestor "$tag" HEAD 2>/dev/null; then
            ins_info "$dir already has $tag"
            return 0
        fi
        if ! git -C "$dir" merge-base --is-ancestor HEAD "$tag" 2>/dev/null; then
            ins_info "$tag does not follow this checkout's commit; leaving it for 'indus update'"
            return 0
        fi
        ins_park_local_changes "$stamp"
        ins_run "Checking out $tag" git -C "$dir" checkout --detach "$tag" ||
            ins_fail "git checkout failed$(ins_cause)" git_checkout_failed
        ins_ok "moved $dir to $tag"
        return 0
    fi
    ins_run "Fetching origin/$IN_BRANCH" git -C "$dir" fetch origin "+refs/heads/$IN_BRANCH:refs/remotes/origin/$IN_BRANCH" ||
        ins_fail "git fetch failed$(ins_cause)" git_fetch_failed
    ins_park_local_changes "$stamp"
    if git -C "$dir" show-ref --verify --quiet "refs/heads/$IN_BRANCH"; then
        ins_run "Checking out $IN_BRANCH" git -C "$dir" checkout "$IN_BRANCH" ||
            ins_fail "git checkout failed$(ins_cause)" git_checkout_failed
    else
        ins_run "Checking out $IN_BRANCH" git -C "$dir" checkout -b "$IN_BRANCH" "origin/$IN_BRANCH" ||
            ins_fail "git checkout failed$(ins_cause)" git_checkout_failed
    fi
    if ins_run --may-fail "Fast-forwarding to origin/$IN_BRANCH" git -C "$dir" merge --ff-only "origin/$IN_BRANCH"; then
        ins_ok "$dir is at origin/$IN_BRANCH"
        return 0
    fi
    # Not a fast-forward: save every commit the reset would drop, and only then reset.
    ahead="$(git -C "$dir" rev-list --count "origin/$IN_BRANCH..HEAD" 2>/dev/null)" ||
        ins_fail "cannot count the local commits; refusing to reset $dir" git_reset_failed
    if [ "$ahead" -gt 0 ]; then
        backup="refs/indus/install-backups/$stamp"
        git -C "$dir" update-ref "$backup" HEAD ||
            ins_fail "cannot save $ahead local commit(s); refusing to reset $dir" git_reset_failed
        ins_warn "$ahead commit(s) not on origin/$IN_BRANCH saved as $backup (git -C \"$dir\" log $backup)"
    fi
    ins_run "Resetting to origin/$IN_BRANCH" git -C "$dir" reset --hard "origin/$IN_BRANCH" ||
        ins_fail "git reset failed$(ins_cause)" git_reset_failed
    ins_warn "$dir could not fast-forward; it now matches origin/$IN_BRANCH"
}

ins_stage_repository() {
    local aside
    if [ -e "$IN_DIR/.git" ] && ! git -C "$IN_DIR" rev-parse --verify -q HEAD >/dev/null 2>&1; then
        aside="$IN_DIR.broken-$(ins_stamp)"
        ins_warn "$IN_DIR holds an interrupted clone (no commits); moving it aside to $aside"
        mv "$IN_DIR" "$aside" || ins_fail "cannot move $IN_DIR aside" filesystem_error
    fi
    if [ -e "$IN_DIR/.git" ]; then
        ins_repo_update
    else
        ins_repo_fresh
    fi
}

# Indus Agent installer: prerequisites, runtime, dependencies, config, products, setup, gateway and
# complete stages (P23-05, R10.16).

# The extras every install gets (INS_EXTRAS_COMMON), and those added unless --skip-browser /
# --skip-computer-use (INS_EXTRAS_BROWSER, INS_EXTRAS_COMPUTER_USE) come from stages.json `extras`
# (the generated stages section), the table install.ps1 reads too.
# curl exit codes that mean "the network failed", the only ones that permit the mirror: could not
# resolve proxy/host, could not connect, partial file, HTTP error (-f), timeout, empty reply,
# send/receive failure.
INS_NETWORK_CODES=' 5 6 7 18 22 28 52 55 56 '
INS_LAUNCHER_MARK='# indus launcher: written by install.sh; `indus uninstall` removes it'
INS_PATH_BEGIN='# >>> indus >>>'
INS_PATH_END='# <<< indus <<<'

ins_venv_bin() { printf '%s/.venv/bin/%s' "$IN_DIR" "$1"; }

# -- prerequisites --------------------------------------------------------------------------------

ins_stage_prerequisites() {
    command -v git >/dev/null 2>&1 ||
        ins_fail "git is required; install it with your system's package manager and rerun" git_missing
    if ! git --version >/dev/null 2>&1; then
        if [ "$(uname -s)" = Darwin ]; then
            ins_fail "git needs Apple's Command Line Tools: run 'xcode-select --install', then rerun this installer" git_missing
        fi
        ins_fail "git is installed but does not run: $(git --version 2>&1 | ins_error_line)" git_missing
    fi
    command -v curl >/dev/null 2>&1 ||
        ins_fail "curl is required; install it with your system's package manager and rerun" curl_missing
    command -v tar >/dev/null 2>&1 ||
        ins_fail "tar is required; install it with your system's package manager and rerun" tar_missing
    command -v sha256sum >/dev/null 2>&1 || command -v shasum >/dev/null 2>&1 ||
        ins_fail "sha256sum or shasum is required to verify downloads" sha256_missing
    ins_log "prerequisites: git, curl, tar and a SHA-256 tool found"
}

# -- runtime: pinned uv and Python ----------------------------------------------------------------

# musl or glibc: the ELF interpreter named in the first 8 KiB of a system binary decides, else
# `ldd --version`, else a musl loader on disk.
ins_libc() {
    local probe head out
    if [ $# -eq 0 ]; then set -- /bin/sh; fi
    for probe in "$@"; do
        head="$(head -c 8192 "$probe" 2>/dev/null | LC_ALL=C tr -d '\000')" || continue
        case "$head" in $'\x7f'ELF*) ;; *) continue ;; esac
        case "$head" in
            *ld-musl-*)
                printf musl
                return 0
                ;;
            *ld-linux*)
                printf glibc
                return 0
                ;;
        esac
    done
    out="$(ldd --version 2>&1 | tr '[:upper:]' '[:lower:]')"
    case "$out" in
        *musl*)
            printf musl
            return 0
            ;;
        *glibc* | *"gnu libc"* | *"gnu c library"*)
            printf glibc
            return 0
            ;;
    esac
    if ls /lib/ld-musl-*.so.1 >/dev/null 2>&1; then printf musl; else printf glibc; fi
}

# The pins key for this host: linux-x64, linux-arm64-musl, darwin-arm64, ...
ins_uv_target() {
    local arch
    case "$(uname -m)" in
        x86_64 | amd64) arch=x64 ;;
        arm64 | aarch64) arch=arm64 ;;
        *) return 1 ;;
    esac
    case "$(uname -s)" in
        Linux)
            if [ "$(ins_libc)" = musl ]; then printf 'linux-%s-musl' "$arch"; else printf 'linux-%s' "$arch"; fi
            ;;
        Darwin) printf 'darwin-%s' "$arch" ;;
        *) return 1 ;;
    esac
}

ins_sha256_file() {
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum "$1" | cut -d' ' -f1
    elif command -v shasum >/dev/null 2>&1; then
        shasum -a 256 "$1" | cut -d' ' -f1
    else
        return 1
    fi
}

# ins_download URL FILE: returns curl's exit status. HTTPS only, redirects included (the digest is
# checked afterwards whatever the origin).
ins_download() {
    ins_log "downloading $1"
    curl -fsSL --proto '=https' --proto-redir '=https' --connect-timeout 20 --max-time 600 \
        -o "$2" "$1"
}

ins_is_network_failure() {
    case "$INS_NETWORK_CODES" in *" $1 "*) return 0 ;; esac
    return 1
}

# The pinned uv under <home>/tools/uv-<version>-<target>/, downloaded and verified if missing.
ins_ensure_uv() {
    [ -z "${INS_UV:-}" ] || return 0
    local target entry tmp rc origin digest found
    target="$(ins_uv_target)" ||
        ins_fail "there is no uv build for $(uname -s) $(uname -m); this system is not supported" unsupported_platform
    ins_uv_pin "$target" ||
        ins_fail "no uv is pinned for $target; this system is not supported" unsupported_platform
    entry="$IN_HOME/tools/uv-$INS_UV_VERSION-$target"
    if [ ! -x "$entry/uv" ]; then
        [ -n "$INS_PIN_SHA256" ] ||
            ins_fail "this installer has no recorded SHA-256 for uv $INS_UV_VERSION ($target) yet, so it downloads nothing; use a released install.sh" download_failed
        tmp="$(mktemp -d 2>/dev/null)" || ins_fail "cannot create a temporary directory" filesystem_error
        INS_CLEANUP="$tmp"
        origin="$INS_PIN_URL"
        ins_download "$INS_PIN_URL" "$tmp/uv.archive"
        rc=$?
        if [ "$rc" -ne 0 ]; then
            ins_is_network_failure "$rc" ||
                ins_fail "downloading uv from $INS_PIN_URL failed (curl exit $rc)" download_failed
            [ -n "$INS_PIN_MIRROR" ] ||
                ins_fail "downloading uv from $INS_PIN_URL failed (curl exit $rc) and there is no mirror" download_failed
            ins_warn "downloading uv failed (curl exit $rc); trying our mirror"
            origin="$INS_PIN_MIRROR"
            rm -f "$tmp/uv.archive"
            ins_download "$INS_PIN_MIRROR" "$tmp/uv.archive"
            rc=$?
            [ "$rc" -eq 0 ] ||
                ins_fail "downloading uv failed from $INS_PIN_URL and from the mirror (curl exit $rc)" download_failed
        fi
        digest="$(ins_sha256_file "$tmp/uv.archive")" ||
            ins_fail "cannot compute the SHA-256 of the uv download" download_failed
        [ "$digest" = "$INS_PIN_SHA256" ] ||
            ins_fail "the uv download from $origin does not match its pinned SHA-256 (expected $INS_PIN_SHA256, got $digest)" download_digest_mismatch
        mkdir -p "$tmp/unpacked" && tar -xzf "$tmp/uv.archive" -C "$tmp/unpacked" 2>/dev/null ||
            ins_fail "cannot unpack the uv archive" uv_unusable
        found="$(find "$tmp/unpacked" -type f -name uv | head -n 1)"
        [ -n "$found" ] || ins_fail "the uv archive holds no uv binary" uv_unusable
        mkdir -p "$entry" || ins_fail "cannot create $entry" filesystem_error
        if [ -f "${found%/uv}/uvx" ]; then mv -f "${found%/uv}/uvx" "$entry/uvx" && chmod 755 "$entry/uvx"; fi
        mv -f "$found" "$entry/uv" && chmod 755 "$entry/uv" ||
            ins_fail "cannot install uv into $entry" filesystem_error
        rm -rf "$tmp"
        INS_CLEANUP=""
    fi
    if ! "$entry/uv" --version >/dev/null 2>&1; then
        rm -rf "$entry"
        ins_fail "the pinned uv does not run on this system" uv_unusable
    fi
    INS_UV="$entry/uv"
    export UV_PYTHON_INSTALL_DIR="$IN_HOME/tools/python"
}

# An interpreter inside the supported range (an existing 3.13/3.14 is fine), else uv installs the
# pinned minor under <home>/tools/python.
ins_find_python() {
    [ -z "${INS_PYTHON:-}" ] || return 0
    local py
    ins_ensure_uv
    py="$("$INS_UV" python find --no-project "$INS_PYTHON_RANGE" 2>/dev/null)" || py=""
    if [ -z "$py" ]; then
        ins_run "Installing Python $INS_PYTHON_VERSION" "$INS_UV" python install --no-bin "$INS_PYTHON_VERSION" ||
            ins_fail "Python $INS_PYTHON_VERSION could not be installed$(ins_cause)" python_install_failed
        py="$("$INS_UV" python find --no-project "$INS_PYTHON_VERSION" 2>/dev/null)" ||
            ins_fail "Python $INS_PYTHON_VERSION was installed but cannot be found" python_install_failed
    fi
    py="${py%$'\r'}"
    [ -x "$py" ] && "$py" --version >/dev/null 2>&1 ||
        ins_fail "the Python interpreter $py does not run" python_install_failed
    INS_PYTHON="$py"
}

ins_stage_runtime() {
    ins_find_python
    ins_ok "uv $INS_UV_VERSION and $("$INS_PYTHON" --version 2>&1) ready"
}

# -- dependencies ---------------------------------------------------------------------------------

# ins_left_out FLAG EXTRAS: true when these extras stay out of this install: this run's skip flag
# says so, or an earlier install saved its extras (updates.installs.<id>.extras) without them. A
# group with no extras is left out only by its flag.
ins_left_out() {
    local saved word
    [ "$1" = false ] || return 0
    [ -n "$2" ] || return 1
    saved="$(ins_install_setting "$IN_DIR" extras 2>/dev/null)"
    [ -n "$saved" ] || return 1
    for word in $2; do
        case " $saved " in *" $word "*) ;; *) return 0 ;; esac
    done
    return 1
}

# The extras this install syncs, in a fixed order: the common ones, then the optional groups that
# are not left out.
ins_extras_words() {
    local words="$INS_EXTRAS_COMMON"
    ins_left_out "$IN_SKIP_BROWSER" "$INS_EXTRAS_BROWSER" || words="$words $INS_EXTRAS_BROWSER"
    ins_left_out "$IN_SKIP_CU" "$INS_EXTRAS_COMPUTER_USE" || words="$words $INS_EXTRAS_COMPUTER_USE"
    printf '%s' "$words"
}

# What is left out, for the person: tool names, not extras.
ins_left_out_words() {
    local out=""
    if ins_left_out "$IN_SKIP_BROWSER" "$INS_EXTRAS_BROWSER"; then out="browser"; fi
    if ins_left_out "$IN_SKIP_CU" "$INS_EXTRAS_COMPUTER_USE"; then out="${out:+$out }computer-use"; fi
    printf '%s' "$out"
}

ins_stage_dependencies() {
    local extras=() word left
    [ -f "$IN_DIR/uv.lock" ] || ins_fail "$IN_DIR has no uv.lock; run the repository stage first" deps_install_failed
    ins_find_python
    for word in $(ins_extras_words); do extras+=(--extra "$word"); done
    left="$(ins_left_out_words)"
    unset UV_PROJECT_ENVIRONMENT VIRTUAL_ENV
    ins_run "Installing the Python packages (hash-checked against uv.lock)" \
        "$INS_UV" sync --directory "$IN_DIR" --frozen --no-dev --python "$INS_PYTHON" "${extras[@]}" ||
        ins_fail "installing the Python packages failed$(ins_cause)" deps_install_failed
    [ -x "$(ins_venv_bin indus)" ] || ins_fail "the indus command is missing after the install" deps_install_failed
    if [ -n "$left" ]; then ins_info "left out: $left"; fi
}

# -- config ---------------------------------------------------------------------------------------

# The installed package's own code makes the home skeleton and seeds config.yaml (the same writer
# `indus config edit` uses), so the installer never duplicates the layout.
INS_SEED_PY='import sys
from pathlib import Path

from indus.cli.commands.config_read import seed_config
from indus.foundation.layout import ensure_home
from indus.foundation.scope import make_scope

scope = make_scope(Path(sys.argv[1]))
ensure_home(scope)
seed_config(scope)'

ins_seed_home() {
    local py
    py="$(ins_venv_bin python)"
    [ -x "$py" ] || ins_fail "the Python environment is missing; run the dependencies stage first" deps_missing
    ins_run "Preparing $IN_HOME" "$py" -I -c "$INS_SEED_PY" "$IN_HOME" ||
        ins_fail "could not prepare $IN_HOME$(ins_cause)" config_failed
}

# ins_set_install_setting NAME VALUE: updates.installs.<id>.<NAME> through `indus config set`
# (the schema key `indus update` reads: channel, extras).
ins_set_install_setting() {
    local id
    id="$(ins_install_id "$IN_DIR")" || return 1
    ins_run --may-fail "Saving updates.installs.$id.$1" \
        "$(ins_venv_bin indus)" config set --force "updates.installs.$id.$1" "$2"
}

ins_stage_config() {
    local words list="" word
    ins_seed_home
    if [ ! -e "$IN_HOME/.env" ]; then
        (umask 077 && : >"$IN_HOME/.env") || ins_fail "cannot create $IN_HOME/.env" config_failed
    fi
    chmod 600 "$IN_HOME/.env" || ins_fail "cannot restrict $IN_HOME/.env to its owner" config_failed
    # The extras this install synced, so `indus update` and later installs keep the same set.
    words="$(ins_extras_words)"
    for word in $words; do list="${list:+$list, }$word"; done
    ins_set_install_setting extras "[$list]" ||
        ins_warn "could not save the extras ($words); later updates may install a different set"
    ins_log "settings ready in $IN_HOME"
}

# -- products -------------------------------------------------------------------------------------

# Paths written into the launcher must survive double quotes in /bin/sh.
ins_plain_path() {
    case "$1" in *'"'* | *'$'* | *'`'* | *'\'* | *$'\n'*) return 1 ;; esac
    return 0
}

ins_publish_launcher() {
    local program="$1" bin="$HOME/.local/bin" launcher tmp
    launcher="$bin/indus"
    ins_plain_path "$program" && ins_plain_path "$IN_HOME" ||
        ins_fail "the install path holds quotes, \$, \` or backslashes; choose another --dir / --indus-home" filesystem_error
    if [ -e "$launcher" ] || [ -L "$launcher" ]; then
        if [ -L "$launcher" ] || ! grep -qF "$INS_LAUNCHER_MARK" "$launcher" 2>/dev/null; then
            ins_warn "$launcher was not written by this installer; leaving it (this install's command: $program)"
            return 0
        fi
    fi
    mkdir -p "$bin" || ins_fail "cannot create $bin" filesystem_error
    tmp="$bin/.indus.$$.tmp"
    {
        printf '#!/bin/sh\n%s\n' "$INS_LAUNCHER_MARK"
        if [ "$IN_HOME" != "$HOME/.indus" ]; then
            # shellcheck disable=SC2016 # the launcher expands it, not this script
            printf 'INDUS_HOME="${INDUS_HOME:-%s}"\nexport INDUS_HOME\n' "$IN_HOME"
        fi
        # shellcheck disable=SC2016
        printf 'exec "%s" "$@"\n' "$program"
    } >"$tmp" && chmod 755 "$tmp" && mv -f "$tmp" "$launcher" ||
        { rm -f "$tmp"; ins_fail "cannot write $launcher" filesystem_error; }
    ins_log "published $launcher"
}

# ins_add_path_block RC BODY: append the marked block once (an existing block is left alone;
# `indus uninstall` removes it by its exact marker lines).
ins_add_path_block() {
    local rc="$1"
    if [ -f "$rc" ] && grep -qxF "$INS_PATH_BEGIN" "$rc"; then return 0; fi
    mkdir -p "$(dirname "$rc")" || ins_fail "cannot create $(dirname "$rc")" filesystem_error
    {
        if [ -s "$rc" ]; then printf '\n'; fi
        printf '%s\n%s\n%s\n' "$INS_PATH_BEGIN" "$2" "$INS_PATH_END"
    } >>"$rc" || ins_fail "cannot update $rc" filesystem_error
    ins_log "added ~/.local/bin to PATH in $rc"
}

ins_wire_path() {
    local posix_line rc zdir
    # shellcheck disable=SC2016 # written to the rc file literally, expanded by the shell that reads it
    posix_line='case ":$PATH:" in *":$HOME/.local/bin:"*) ;; *) export PATH="$HOME/.local/bin:$PATH" ;; esac'
    case "$(basename "${SHELL:-/bin/bash}")" in
        zsh)
            zdir="${ZDOTDIR:-$HOME}"
            ins_add_path_block "$zdir/.zshrc" "$posix_line"
            ins_add_path_block "$zdir/.zprofile" "$posix_line"
            ;;
        fish)
            # shellcheck disable=SC2016
            ins_add_path_block "$HOME/.config/fish/config.fish" 'fish_add_path "$HOME/.local/bin"'
            ;;
        *)
            ins_add_path_block "$HOME/.bashrc" "$posix_line"
            ins_add_path_block "$HOME/.profile" "$posix_line"
            # A login bash reads only the first of these it finds, before .profile.
            for rc in "$HOME/.bash_profile" "$HOME/.bash_login"; do
                if [ -f "$rc" ]; then ins_add_path_block "$rc" "$posix_line"; fi
            done
            ;;
    esac
}

# A checkout serves its own built pages (apps/web/dist) when a developer built them; otherwise a
# release install gets the pages that release was built with: `python -m indus.web.bundle fetch`
# checks them against the manifest digest the release tag records and publishes them into
# src/indus/web/static (F-3). Never fatal: without pages the dashboard's API still works.
ins_web_pages() {
    local rc=0
    if [ -f "$IN_DIR/apps/web/dist/index.html" ]; then
        ins_log "the dashboard pages are built in this checkout (apps/web/dist)"
        return 0
    fi
    ins_run --may-fail "Fetching the dashboard pages" \
        "$(ins_venv_bin python)" -m indus.web.bundle fetch --repo "$IN_DIR" \
        --target "$IN_DIR/src/indus/web/static" || rc=$?
    case "$rc" in
        0) ins_log "the dashboard pages of this release are in place" ;;
        3) ins_info "This checkout is not on a release, so it has no prebuilt dashboard pages; build them with: pnpm install && pnpm --filter @indus/web build" ;;
        *) ins_warn "the dashboard pages could not be fetched$(ins_cause); 'indus dashboard' serves only its API until they are (rerun the installer, or build them with pnpm --filter @indus/web build)" ;;
    esac
    return 0
}

ins_stage_products() {
    local program
    program="$(ins_venv_bin indus)"
    [ -x "$program" ] || ins_fail "$program is missing; run the dependencies stage first" deps_missing
    ins_publish_launcher "$program"
    ins_web_pages
    if [ "$IN_DESKTOP" = true ]; then
        ins_warn "install.sh does not build the desktop app; download it from the release page (it uses this runtime)"
    fi
    ins_wire_path
}

ins_path_hint() {
    case ":$PATH:" in *":$HOME/.local/bin:"*) return 0 ;; esac
    case "$(basename "${SHELL:-/bin/bash}")" in
        zsh) ins_info "Open a new terminal (or run: source ~/.zshrc) to use the indus command" ;;
        fish) ins_info "Open a new terminal (or run: source ~/.config/fish/config.fish) to use the indus command" ;;
        *) ins_info "Open a new terminal (or run: source ~/.bashrc) to use the indus command" ;;
    esac
}

# -- setup and gateway (a person at a terminal only) ----------------------------------------------

# Under `curl | bash` stdin is the script, so the questions go to the terminal itself; opening it
# fails without one (a container build, the desktop's runner).
ins_has_tty() { (: </dev/tty) 2>/dev/null; }

ins_stage_setup() {
    ins_has_tty || ins_skip "no terminal; run 'indus setup' later"
    "$(ins_venv_bin indus)" setup </dev/tty ||
        ins_fail "provider setup did not finish; run 'indus setup' to try again" setup_failed
}

ins_stage_gateway() {
    local answer=""
    ins_has_tty || ins_skip "no terminal; run 'indus gateway install' later"
    printf 'Run the messaging gateway as a background service now? [y/N] '
    IFS= read -r answer </dev/tty || answer=""
    case "$answer" in
        y | Y | yes | YES) ;;
        *) ins_skip "not requested; run 'indus gateway install' any time" ;;
    esac
    "$(ins_venv_bin indus)" gateway install </dev/tty ||
        ins_fail "the gateway service was not installed; run 'indus gateway install' to try again" gateway_failed
}

# -- complete -------------------------------------------------------------------------------------

ins_stage_complete() {
    local commit url saved="" channel marker tmp version
    commit="$(git -C "$IN_DIR" rev-parse HEAD 2>/dev/null)" ||
        ins_fail "$IN_DIR is not a checkout; run the repository stage first" other
    url="$(git -C "$IN_DIR" config --get remote.origin.url 2>/dev/null)" || url=""
    [ -n "$IN_CHANNEL$IN_COMMIT" ] || saved="$(ins_saved_channel "$IN_DIR")"
    channel="$(ins_effective_channel "$url" "$saved")"
    marker="$IN_DIR/.indus-bootstrap.json"
    tmp="$marker.$$.tmp"
    # The release HEAD is on (newest when several), for `indus --version` (F-4); "" on main.
    version="$(git -C "$IN_DIR" tag --points-at HEAD --list 'v*' 2>/dev/null | ins_newest_tag canary)"
    version="${version#v}"
    printf '{"schema":1,"commit":%s,"branch":%s,"channel":%s,"version":%s,"completed_at":"%s"}\n' \
        "$(ins_json_string "$commit")" "$(ins_json_string "$IN_BRANCH")" \
        "$(ins_json_string "$channel")" "$(ins_json_string "$version")" "$(ins_now)" >"$tmp" &&
        mv -f "$tmp" "$marker" ||
        { rm -f "$tmp"; ins_fail "cannot write $marker" filesystem_error; }
    if [ -n "$IN_CHANNEL" ]; then
        ins_set_install_setting channel "$IN_CHANNEL" ||
            ins_warn "could not save the $IN_CHANNEL channel; 'indus update --set-channel $IN_CHANNEL' does it"
    fi
    ins_ok "Indus Agent is installed. Run: indus"
}

